// Expo config plugin for the app database module (modules/lophn-app-db). android/ is generated by prebuild and not
// committed, so the one line the module needs there is written here, once, however often prebuild runs: MainApplication
// registers the module's package with the sandbox as a substitution package. A guest that lists LophnAppDb as a
// substitution of itself then gets its own instance, told its origin, which opens only the file the host bound to it.
// The R8 keep rule ships with the module (its consumer ProGuard file).
const { withMainApplication } = require("expo/config-plugins");

const REGISTER =
  "io.callstack.rnsandbox.SandboxReactNativeDelegate.registerSubstitutionPackages(dev.lophn.appdb.LophnAppDbPackage())";
const AFTER = "loadReactNative(this)";

module.exports = function withAppDb(config) {
  return withMainApplication(config, (mod) => {
    if (!mod.modResults.contents.includes(REGISTER)) {
      if (!mod.modResults.contents.includes(AFTER)) {
        throw new Error(`with-app-db: MainApplication has no ${AFTER}`);
      }
      mod.modResults.contents = mod.modResults.contents.replace(AFTER, `${AFTER}\n    ${REGISTER}`);
    }
    return mod;
  });
};
